"""Ordered-storage interface.

The baseline library exposes a ``SortedList``; the branchable experiment engine
keeps it for the public/auxiliary ordered view and adds what the protocol
needs:

* :class:`PifoStore` - one per bank, ordered by the immutable ``(rank, ordinal)``
  key, with O(1) removal at a cached position so cancellation and refill
  pushout stay cheap on large backlogs.
* :class:`RankIndex` - the global live set (staging FIFOs *and* PIFOs) ordered
  by rank, answering "how many live packets have a strictly smaller rank"
  (the reported ``rank_error``) in O(n ** 0.6) instead of a whole-backlog scan.

Both are segmented (sqrt-style) ordered lists: segments hold parallel key and
payload lists plus a length table, so no operation repeats whole-backlog work.
Save/restore branches reuse checkpoint segments without copying them and merge
them in sorted order.
"""
from bisect import bisect_left as _bisect_left

_MIN_SEG = 24


class SortedList:
    """Plain ordered list, kept for the baseline library API."""

    def __init__(self, iterable=None):
        self._items = []
        if iterable is not None:
            for item in iterable:
                self.add(item)

    def add(self, item):
        self._items.insert(_bisect_left(self._items, item), item)

    def pop(self, index=-1):
        return self._items.pop(index)

    def remove(self, item):
        self._items.remove(item)

    def clear(self):
        self._items.clear()

    def bisect_left(self, item):
        return _bisect_left(self._items, item)

    def __bool__(self):
        return bool(self._items)

    def __len__(self):
        return len(self._items)

    def __iter__(self):
        return iter(self._items)

    def __getitem__(self, index):
        return self._items[index]


def _target(total):
    """Balanced segment size: prefix sums cost O(segments), inserts O(target)."""
    step = int(total ** 0.6) + _MIN_SEG
    return step if step > _MIN_SEG else _MIN_SEG


class _Segmented:
    """Segmented ordered container.

    Payloads must provide ``key()`` returning a totally ordered value and a
    mutable ``pos`` attribute holding the payload's global ordered index.
    Keys are compared with ``<`` only.
    """

    __slots__ = ('_keys', '_vals', '_lens', '_total')

    def __init__(self, segments=None):
        if segments is None:
            self._keys = []
            self._vals = []
            self._lens = []
            self._total = 0
        else:
            self._keys, self._vals, self._lens = segments
            self._total = sum(self._lens)

    # -- segment table maintenance -----------------------------------------
    def _rebalance(self):
        flat = []
        for seg in self._vals:
            flat.extend(seg)
        total = len(flat)
        size = _target(total)
        vals = [flat[i:i + size] for i in range(0, total, size)]
        self._vals = vals
        self._keys = [[v.key() for v in seg] for seg in vals]
        self._lens = [len(seg) for seg in vals]
        self._total = total

    def _compact(self):
        """Merge neighbouring small segments; keeps ordering invariants."""
        vals, keys, lens = self._vals, self._keys, self._lens
        if len(vals) < 2:
            return
        size = _target(self._total)
        i = 0
        changed = False
        while i + 1 < len(vals):
            if lens[i] + lens[i + 1] <= size and keys[i][-1] < keys[i + 1][0]:
                vals[i] = vals[i] + vals[i + 1]
                keys[i] = keys[i] + keys[i + 1]
                lens[i] = lens[i] + lens[i + 1]
                del vals[i + 1]
                del keys[i + 1]
                del lens[i + 1]
                changed = True
                continue
            i += 1
        if changed and len(vals) * _MIN_SEG > self._total * 4 + 4096:
            self._rebalance()

    def _split(self, idx):
        vals, keys, lens = self._vals, self._keys, self._lens
        half = lens[idx] >> 1
        vals.insert(idx + 1, vals[idx][half:])
        keys.insert(idx + 1, keys[idx][half:])
        lens.insert(idx + 1, lens[idx] - half)
        del vals[idx][half:]
        del keys[idx][half:]
        lens[idx] = half
        if len(vals) * _MIN_SEG > self._total * 4 + 4096:
            self._rebalance()

    # -- ordered queries ----------------------------------------------------
    def _segment_of(self, key):
        """First segment whose last key is not smaller than ``key``."""
        keys = self._keys
        lo, hi = 0, len(keys)
        while lo < hi:
            mid = (lo + hi) >> 1
            if keys[mid][-1] < key:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def count_lt(self, key):
        lens = self._lens
        idx = self._segment_of(key)
        total = sum(lens[:idx])
        if idx < len(lens):
            total += _bisect_left(self._keys[idx], key)
        return total

    def count_le(self, key):
        lens = self._lens
        keys = self._keys
        lo, hi = 0, len(keys)
        while lo < hi:
            mid = (lo + hi) >> 1
            if key < keys[mid][0]:
                hi = mid
            else:
                lo = mid + 1
        idx = lo
        total = sum(lens[:idx])
        if idx < len(keys):
            seg = keys[idx]
            p = _bisect_left(seg, key)
            q = p
            n = len(seg)
            while q < n and not (key < seg[q]):
                q += 1
            total += q
        return total

    def items(self):
        for seg in self._vals:
            for value in seg:
                yield value

    def __bool__(self):
        return self._total != 0

    def __len__(self):
        return self._total

    def __iter__(self):
        return self.items()

    # -- mutation -----------------------------------------------------------
    def add(self, value):
        key = value.key()
        keys, vals, lens = self._keys, self._vals, self._lens
        idx = self._segment_of(key)
        if idx >= len(keys) or not (keys[idx][0] < key):
            keys.insert(idx, [key])
            vals.insert(idx, [value])
            lens.insert(idx, 1)
        else:
            seg_k = keys[idx]
            p = _bisect_left(seg_k, key)
            seg_k.insert(p, key)
            vals[idx].insert(p, value)
            lens[idx] += 1
        self._total += 1
        if lens[idx] > (_target(self._total) << 1):
            self._split(idx)

    def remove(self, value):
        """Remove by identity, using the payload's cached ordered position."""
        return self.remove_at(value.pos)

    def remove_at(self, index):
        keys, vals, lens = self._keys, self._vals, self._lens
        i = self._segment_of_index(index)
        acc = index - self._base(i)
        value = vals[i][acc]
        del vals[i][acc]
        del keys[i][acc]
        lens[i] -= 1
        self._total -= 1
        if not lens[i]:
            del vals[i]
            del keys[i]
            del lens[i]
        else:
            for later in vals[i][acc:]:
                later.pos -= 1
            for j in range(i + 1, len(vals)):
                for later in vals[j]:
                    later.pos -= 1
        return value

    def _base(self, i):
        return sum(self._lens[:i])

    def _segment_of_index(self, index):
        lens = self._lens
        acc = 0
        for i, n in enumerate(lens):
            if index < acc + n:
                return i
            acc += n
        raise IndexError('ordered index out of range')

    def pop_first(self):
        if not self._total:
            return None
        vals, keys, lens = self._vals, self._keys, self._lens
        value = vals[0].pop(0)
        keys[0].pop(0)
        lens[0] -= 1
        self._total -= 1
        if not lens[0]:
            del vals[0]
            del keys[0]
            del lens[0]
        return value

    def pop_last(self):
        if not self._total:
            return None
        vals, keys, lens = self._vals, self._keys, self._lens
        i = len(vals) - 1
        value = vals[i].pop()
        keys[i].pop()
        lens[i] -= 1
        self._total -= 1
        if not lens[i]:
            del vals[i]
            del keys[i]
            del lens[i]
        return value

    def peek(self):
        if not self._total:
            return None
        return self._vals[0][0]

    def clear(self):
        self._keys = []
        self._vals = []
        self._lens = []
        self._total = 0

    def segments(self):
        return (self._keys, self._vals, self._lens)

    def adopt(self, other):
        """Merge another container's segments in, keeping key order.

        The adopted segments are shared (not copied); their payloads are
        distinct from this container's.  Used when a save/restore branch
        resumes from a checkpoint.
        """
        keys, vals, lens = self._keys, self._vals, self._lens
        okeys, ovals, olens = other._keys, other._vals, other._lens
        nk, nv, nl = [], [], []
        i = j = 0
        while i < len(keys) and j < len(okeys):
            if keys[i][0] < okeys[j][0]:
                nk.append(keys[i]); nv.append(vals[i]); nl.append(lens[i]); i += 1
            else:
                nk.append(okeys[j]); nv.append(ovals[j]); nl.append(olens[j]); j += 1
        while i < len(keys):
            nk.append(keys[i]); nv.append(vals[i]); nl.append(lens[i]); i += 1
        while j < len(okeys):
            nk.append(okeys[j]); nv.append(ovals[j]); nl.append(olens[j]); j += 1
        self._keys, self._vals, self._lens = nk, nv, nl
        self._total += other._total
        other._keys, other._vals, other._lens, other._total = [], [], [], 0
        self._rebuild_positions()
        self._compact()

    def _rebuild_positions(self):
        index = 0
        for seg in self._vals:
            for value in seg:
                value.pos = index
                index += 1

    def extend_sorted(self, values):
        """Append payloads whose keys are not smaller than every stored key."""
        if not values:
            return
        vals, keys, lens = self._vals, self._vals and self._keys, self._lens
        for value in values:
            key = value.key()
            if lens and not (keys[-1][-1] < key) and not (keys[-1][-1] == key):
                raise ValueError('extend_sorted requires ordered input')
            value.pos = self._total
            self._total += 1
            if lens and lens[-1] < (_target(self._total) << 1):
                keys[-1].append(key)
                vals[-1].append(value)
                lens[-1] += 1
            else:
                keys.append([key])
                vals.append([value])
                lens.append(1)


class PifoStore(_Segmented):
    """Per-bank PIFO: ordered by ``(rank, ordinal)``, positional removal."""

    __slots__ = ('_keys', '_vals', '_lens', '_total')


class RankIndex(_Segmented):
    """Global live-set rank index for strict-rank prefix counts."""

    __slots__ = ('_keys', '_vals', '_lens', '_total')


def merge_segment_lists(left, right):
    """Merge two checkpoint segment tables into one ordered table."""
    out = _Segmented()
    out._keys = left[0] + right[0]
    out._vals = left[1] + right[1]
    out._lens = left[2] + right[2]
    out._total = sum(out._lens)
    if len(out._vals) > 1:
        out._rebalance()
    return out.segments()
